fn round_even(x:f64,p:i64)f64{var scale:f64=1.0;var i:i64=0;while(i<p):(i+=1){scale*=10.0;}const y=x*scale;var lower:i64=@intFromFloat(y);const fraction=y-@as(f64,@floatFromInt(lower));if(fraction>0.5 or (fraction==0.5 and @mod(lower,2)!=0))lower+=1;return @as(f64,@floatFromInt(lower))/scale;}
export fn integration_by_simpson_approx(v:[*]const i64,n:usize)f64{if(n!=3)return -1.0e300;const a=v[0];const b=v[1];const p=v[2];if(a < -10 or a>10 or b < -10 or b>10 or a>=b or p<0 or p>4)return -1.0e300;const h=@as(f64,@floatFromInt(b-a))/1000.0;var total=@as(f64,@floatFromInt(a*a+b*b));for(1..1000)|i|{const x=@as(f64,@floatFromInt(a))+h*@as(f64,@floatFromInt(i));total+=x*x*(if(i%2==1)4.0 else 2.0);}total*=h/3.0;return round_even(total,p);}
